import os


def read_file(root: str, name: str):
    root_path = os.path.realpath(root)
    target = os.path.realpath(os.path.join(root_path, name))
    if target != root_path and not target.startswith(root_path + os.sep):
        raise ValueError("refusing to read outside root")
    with open(target) as f:
        return f.read()
